        ('schedule_feed_ingests', 'schedule_ingest', 'SELECT', 'delivered_at'),
        ('ingest_active_tracked_trains', 'trust_consumer', 'SELECT', ''),
        ('ingest_sample_station_pins', 'ldbws_ro', 'SELECT', ''),
